/* New-character UI. Old characters stay on their original rules until a new life is made. */
(function(){'use strict';const N=DecideCreation;let d=null;
const host=document.createElement('article');host.id='pointBuy';$('creationSummary').before(host);
const mode=document.createElement('article');mode.innerHTML='<h2>เพศตัวละคร</h2><div id="genderChoices" class="choices"></div><p>เพศไม่เปลี่ยนค่าสถานะหรือความสามารถ</p><h2>เลือกเส้นทางของคุณ</h2><p>เลือกเผ่าและคลาสเอง หรือสุ่มครั้งเดียว • ทั้งสองทางใช้แต้มซื้อ Unique ได้เหมือนกัน</p><button type="button" id="rollIdentity">สุ่มเผ่าและคลาสครั้งเดียว</button><p id="rollStatus" role="status"></p><h2>Unique & Proficiency Point Buy</h2><p id="uniqueBudget" role="status"></p><p>ใช้แต้มร่วมกับความชำนาญตามเผ่า • แต่ละ Unique มีราคาต่างกัน เลือกได้สูงสุด 1 สกิล • Stat แยก 27 แต้ม</p><button type="button" id="clearUnique">คืนแต้ม Unique</button><div id="uniqueChoices" class="choices"></div><p id="uniqueStatus" role="status" aria-live="polite"></p>';$('raceChoices').parentNode.insertBefore(mode,$('raceChoices').previousElementSibling);
const key=()=>storageKey+':creation-draft';
function persist(){if(!d)return;d.name=$('characterName').value;localStorage.setItem(key(),JSON.stringify(d));}
function open(){try{const stored=JSON.parse(localStorage.getItem(key()));d=N.upgradeDraft(stored);if(stored.v<3)$('createStatus').textContent='อัปเดตร่างตามพื้นฐานและงบเผ่าใหม่แล้ว • หากงบเกินจะคืนแต้มความชำนาญให้จัดใหม่ ตัวละครที่สร้างเสร็จไม่เปลี่ยน';}catch{d=N.draft();}$('characterName').value=d.name||'';paint();}
function paint(){if(!d)return;$('genderChoices').innerHTML=Object.entries(N.genders).map(([id,name])=>`<label class="choice"><input type="radio" name="gender" value="${id}" ${d.gender===id?'checked':''}><span>${name}</span></label>`).join('');document.querySelectorAll('[name=gender]').forEach(el=>el.onchange=()=>{d.gender=el.value;persist();paint();});const race=N.races[d.race],job=N.classes[d.job];$('raceChoices').innerHTML=Object.entries(N.races).map(([id,r])=>`<label class="choice"><input type="radio" name="race" value="${id}" ${d.race===id?'checked':''} ${d.rolled?'disabled':''}><span><strong>${r.name}</strong><small>${r.trait}</small><small>แต้มร่วม ${N.uniqueBudget({...d,race:id})} • พื้นฐาน ${Object.entries(N.baseStats({...d,race:id})).map(([k,v])=>k+' '+v).join(' / ')}</small></span></label>`).join('');$('classChoices').innerHTML=Object.entries(N.classes).map(([id,j])=>`<label class="choice"><input type="radio" name="job" value="${id}" ${d.job===id?'checked':''} ${d.rolled?'disabled':''}><span><strong>${j.name}</strong><small>${j.skills.map(k=>N.skills[k].name).join(' / ')}</small></span></label>`).join('');
 document.querySelectorAll('[name=race],[name=job]').forEach(el=>el.onchange=()=>{if(d.rolled)return;if(el.name==='race'){d=N.changeRace(d,el.value);$('createStatus').textContent='เปลี่ยนเผ่าแล้ว • คืนแต้ม Stat ให้จัดใหม่ และคืนแต้มความชำนาญหากเกินงบเผ่า';}else{d.job=el.value;d.weapon=N.classes[d.job].starter[0];}persist();paint();});$('rollIdentity').disabled=d.rolled;$('rollStatus').textContent=d.rolled?'ผลเผ่าและคลาสถูกล็อกแล้ว • จัดแต้มและเลือกซื้อ Unique ได้เอง':'เลือกเผ่าและคลาสเอง แล้วใช้แต้มซื้อ Unique ได้ทุกสกิล';$('uniqueBudget').textContent='เหลือ '+(N.uniqueBudget(d)-N.sharedCost(d))+' / '+N.uniqueBudget(d)+' แต้มร่วม • เผ่า '+race.name;$('uniqueChoices').innerHTML=N.uniques.map(u=>{const id=u.id;return `<label class="choice"><input type="radio" name="unique" value="${id}" ${d.unique===id?'checked':''}><span><strong>${u.name} · ${u.price} แต้ม</strong><small>${u.description}</small></span></label>`;}).join('');document.querySelectorAll('[name=unique]').forEach(el=>el.onchange=()=>{try{d=N.validateDraft({...d,unique:el.value});persist();$('createStatus').textContent=$('uniqueStatus').textContent='';}catch(err){$('createStatus').textContent=$('uniqueStatus').textContent='แต้มร่วมไม่พอ • คืนแต้มความชำนาญให้เพียงพอตามราคาของ Unique ที่เลือก';}paint();});
 const final=N.finalStats(d);host.innerHTML=`<h2>ค่าสถานะ · เหลือ ${27-N.cost(d)} / 27 แต้ม</h2><p>เริ่มจากพื้นฐานเผ่า ซื้อเพิ่มได้ถึง 15 ก่อนโบนัสเผ่า • ค่าถาวรสูงสุด 99</p><button type="button" id="recommendBuild">จัดแต้มแนะนำตามคลาส</button><div class="choices">${N.stats.map(k=>`<label>${k}<select data-stat="${k}">${Array.from({length:16-N.baseStats(d)[k]},(_,i)=>{const value=N.baseStats(d)[k]+i;return `<option value="${value}" ${d.base[k]===value?'selected':''}>${value} · ${N.statCost(d,k,value)} แต้ม</option>`;}).join('')}</select><small>พื้นฐาน ${N.baseStats(d)[k]} + อัป ${d.base[k]-N.baseStats(d)[k]} + โบนัสเผ่า ${final[k]-d.base[k]} = ${final[k]}</small></label>`).join('')}</div>${d.race==='human'?`<fieldset><legend>มนุษย์: เลือก +1 สามค่า</legend>${N.stats.map(k=>`<label style="display:inline-block;margin:8px"><input type="checkbox" data-human="${k}" ${d.human.includes(k)?'checked':''}> ${k}</label>`).join('')}</fieldset>`:''}<h2>ความชำนาญ · เหลือ ${N.uniqueBudget(d)-N.sharedCost(d)} / ${N.uniqueBudget(d)} แต้มร่วม</h2><p>D = 1 แต้ม · C = 3 แต้มรวม • ใช้แต้มกองเดียวกับ Unique • B–S และอาวุธคู่ต้องเรียนระหว่างเล่น</p><div class="choices">${Object.entries(N.profs).map(([id,n])=>`<label>${n}<small>${N.profDescriptions[id]}</small><select data-prof="${id}"><option value="">ยังไม่ฝึก</option><option value="D" ${d.profs[id]==='D'?'selected':''}>D · 1 แต้ม</option><option value="C" ${d.profs[id]==='C'?'selected':''}>C · 3 แต้ม</option></select></label>`).join('')}</div><h2>อุปกรณ์เริ่มต้น</h2><label>อาวุธ<select id="starterWeapon">${job.starter.map(k=>`<option value="${k}" ${d.weapon===k?'selected':''}>${N.weapons[k].name}</option>`).join('')}</select></label><p>เกราะ${job.armor}${d.job==='knight'?' + โล่':''} • ยาฟื้น HP ${d.job==='alchemist'?5:3} ขวด • ไม่มีรูน/วิญญาณ${d.job==='alchemist'?' • สารปรุง 3 หน่วย':''}</p>`;
 const update=(fn)=>{try{const next=JSON.parse(JSON.stringify(d));fn(next);d=N.validateDraft(next);persist();$('createStatus').textContent='';}catch(err){$('createStatus').textContent=err.message;}paint();};host.querySelectorAll('[data-stat]').forEach(el=>el.onchange=()=>update(x=>x.base[el.dataset.stat]=Number(el.value)));host.querySelectorAll('[data-prof]').forEach(el=>el.onchange=()=>update(x=>{if(el.value)x.profs[el.dataset.prof]=el.value;else delete x.profs[el.dataset.prof];}));host.querySelectorAll('[data-human]').forEach(el=>el.onchange=()=>{let chosen=[...host.querySelectorAll('[data-human]:checked')].map(x=>x.dataset.human);if(chosen.length===3)update(x=>x.human=chosen);else $('createStatus').textContent='เลือกโบนัสมนุษย์ให้ครบสามค่าก่อนยืนยัน';});$('recommendBuild').onclick=()=>{d=N.recommend(d);persist();paint();};$('starterWeapon').onchange=e=>update(x=>x.weapon=e.target.value);
 $('creationSummary').innerHTML=`<h2>${race.name} · ${job.name}</h2><p>เพศ: ${N.genders[d.gender]}</p><p>Passive: <strong>${job.passive}</strong> — ${N.passiveDescriptions[d.job]}</p>${job.skills.map(k=>`<p><strong>${N.skills[k].name}</strong> — ${N.skills[k].description} · ${N.skills[k].cost} MP · CD ${N.skills[k].cd}</p>`).join('')}<p>${d.unique?'Unique: '+N.uniques.find(x=>x.id===d.unique).name:'ไม่มี Unique ที่เลือก'} • เงินเริ่มต้น 120 เหรียญ</p>`;
}
$('clearUnique').onclick=()=>{d.unique=null;$('uniqueStatus').textContent='คืนแต้ม Unique แล้ว';persist();paint();};
$('rollIdentity').onclick=()=>{try{const next=N.roll(d);localStorage.setItem(key(),JSON.stringify(next));d=next;paint();}catch(e){$('createStatus').textContent=e.message;}};$('characterName').addEventListener('input',()=>{try{persist();}catch(e){$('createStatus').textContent='บันทึกร่างในเครื่องไม่สำเร็จ';}});
$('createForm').onsubmit=e=>{e.preventDefault();try{if(d.race==='human'&&host.querySelectorAll('[data-human]:checked').length!==3)throw Error('เลือกโบนัสมนุษย์สามค่า');const next=newDraft?R.fresh():JSON.parse(JSON.stringify(s));R.createCharacter(next,$('characterName').value,d.race,d.job,DB,d);next.character.images=EverTaleCharacterArt.creationImages();if(s.character)localStorage.setItem(storageKey+':backup',JSON.stringify(s));s=next;R.log(s,'เริ่มชีวิตใหม่ • '+s.character.name);save();localStorage.removeItem(key());d=null;fields();show('gameScreen');}catch(err){$('createStatus').textContent=err.message;}};
function character(){const c=s.character;if(c?.design!==1)return;const panel=$('characterPanel'),side=panel.children[1];if(!side)return;side.innerHTML=`<p>${N.races[c.race].name} · ${N.classes[c.job].name} • เพศ: ${N.genders[c.gender]||N.genders.unspecified}</p><p>Passive: ${N.classes[c.job].passive} — ${N.passiveDescriptions[c.job]}</p><p>Unique: ${N.uniques.find(x=>x.id===c.unique)?.name||'ไม่มี'}</p><p>อาวุธ: ${N.weapons[c.equipment.main].name}${c.equipment.off==='shield'?' + โล่':c.equipment.off?' + '+N.weapons[c.equipment.off].name:''}</p><h3>ความชำนาญ</h3><p>${Object.entries(c.proficiencyGrades).map(([k,v])=>`${N.profs[k]||'Dual Wield'}: <b>${v}</b>`).join(' · ')||'ยังไม่ฝึก'}</p><h3>สกิลเริ่มต้น</h3>${c.skills.map(k=>`<p>${N.skills[k].name} — ${N.skills[k].description}</p>`).join('')}<p class="muted">ใช้สกิลจากเมนูในสนามต่อสู้</p>`;training(panel,c);}

function training(panel,c){
 const P=DecideProgression,box=document.createElement('details');box.id='trainingPanel';box.innerHTML=`<summary>อุปกรณ์และการฝึก</summary><p>ฝึกจริง: D ที่20 EXP / C ที่100 EXP • เลื่อนขั้นกับครู: B 300 EXP/ชนะ3/เลเวล3/100เหรียญ, A 900/ชนะ10/เลเวล10/250เหรียญ, S 2500/ชนะ25/เลเวล20/500เหรียญ</p><p>ชัยชนะ ${c.victories||0} ครั้ง</p><label>ความชำนาญ<select id="trainProficiency">${Object.entries(c.proficiencyGrades).filter(([k])=>N.profs[k]).map(([k,v])=>`<option value="${k}">${N.profs[k]}: ${v} · ฝึก ${c.practice[k]||0} EXP</option>`).join('')}</select></label><button id="promoteProficiency">เข้าทดสอบเลื่อนแรงก์</button><p>เวทพื้นฐาน: INT 10 / 20 เหรียญต่อบท</p><select id="teacherSpell">${['bolt','fire','frost','quagmire','lightning','wind'].filter(k=>!c.skills.includes(k)).map(k=>`<option value="${k}">${N.skills[k].name}</option>`).join('')}</select><button id="learnStarterSpell">เรียนเวทกับครู</button><p>อาวุธฝึก: 25 เหรียญต่อชิ้น • ทุกชิ้นเลเวล1 และจำกัดคลาส</p><select id="buyWeaponChoice">${Object.values(N.weapons).filter(w=>N.classes[c.job].weapons.includes(w.type)).map(w=>`<option value="${w.id}">${w.name} (${w.hands} มือ)</option>`).join('')}</select><button id="buyTrainingWeapon">ซื้ออาวุธฝึก</button><label>มือหลัก<select id="equipMain">${[...new Set(c.inventory.weapons)].map(k=>`<option value="${k}" ${c.equipment.main===k?'selected':''}>${N.weapons[k].name}</option>`).join('')}</select></label><label>มือรอง<select id="equipOff"><option value="">ว่าง</option>${c.job==='knight'?'<option value="shield">โล่</option>':''}${c.proficiencyGrades.dual?[...new Set(c.inventory.weapons)].filter(k=>N.weapons[k].hands===1).map(k=>`<option value="${k}">${N.weapons[k].name}</option>`).join(''):''}</select></label><button id="applyEquipment">สวมอุปกรณ์</button><p>อาวุธคู่: พบศาลาป่า + อาวุธมือเดียว B + 200 เหรียญ แล้วชนะครูในการต่อสู้เดี่ยวด้วยอาวุธคู่ยืมฝึก</p><button id="dualTrial">เริ่มบททดสอบ Dual Wield</button><p id="trainingStatus" role="status"></p>`;panel.append(box);$('equipOff').value=c.equipment.off||'';
 const run=fn=>{try{fn();save();render();status('บันทึกการฝึกและอุปกรณ์แล้ว');}catch(e){$('trainingStatus').textContent=e.message;}};
 $('promoteProficiency').onclick=()=>run(()=>P.promote(s,$('trainProficiency').value));$('learnStarterSpell').onclick=()=>run(()=>P.learnSpell(s,$('teacherSpell').value));$('buyTrainingWeapon').onclick=()=>run(()=>P.buy(s,$('buyWeaponChoice').value));$('applyEquipment').onclick=()=>run(()=>P.changeEquipment(s,$('equipMain').value,$('equipOff').value||null));
 $('dualTrial').onclick=()=>{try{const weapon=P.dualReady(s),D=EverTaleBattleData,scene=D.generate('dual-trial','meadow',12,10,'DUAL-TRIAL');for(const t of scene.cells)Object.assign(t,D.tile());scene.name='บททดสอบอาวุธคู่';scene.cells[50].spawn='player';scene.cells[54].spawn='enemy';const e=DecideCombatRules.create(scene,s,[{name:'ครูฝึกอาวุธคู่',hp:70,str:20}],crypto.randomUUID(),Math.random,{tactical:true});e.training='dual';e.units[0].main=weapon.id;e.units[0].off=weapon.id;e.units[0].grades.dual='D';e.units[0].range=weapon.range;s.gold-=200;s.expedition=e;R.clock(s,120);s.energy-=15;s.turn++;save();EverTaleCombat.launch();}catch(e){$('trainingStatus').textContent=e.message;}};
}

window.DecideCreationUI={open,character};})();
